#ifdef CYCLE_PROFILE
// Cycle profile in CPU cycles (168 MHz), read with the debugger without halting.
// Build: PLATFORMIO_BUILD_FLAGS=-DCYCLE_PROFILE pio run -e genericSTM32F407VGT6
#include <SPI.h>
extern "C" volatile uint8_t spi_use_fast;  // lib/soes/hal/ax58100/spi_utils.cpp
extern "C" volatile uint8_t coe_pdo_fast;  // lib/soes/esc_coe.c
extern "C" void spi_fast_transfer(const uint8_t *tx, uint8_t *rx, uint16_t n);
extern "C" void spi_select(int8_t board);
extern "C" void spi_unselect(int8_t board);
struct CycleProfile {
  uint32_t magic, n;
  uint32_t alevent, digOut, inputs, axes, stepFreq, restart, digIn, total, maxTotal;
  uint32_t benchRuns, pulses100;          // 100 x makeAllPulses, called directly
  uint32_t loopIdle, loopIsr, isrCount;   // busy loop counts without / with the base timer
  uint32_t spiHal75, spiFast75, spiSame;  // ESC_read of 75 bytes, SPI.transfer / register loop
  uint32_t rawFast75, rawHal75, csPair, addr2;  // the parts: transfer only, CS low+high, address
  uint32_t rawPipe75, pipeSame, cr1, cr2, sr;
  uint32_t pack75, unpack54, core400Active;  // 100 x 4 channels stepping, on copies
  uint32_t pack75Old, unpack54Old;
  uint32_t upd, axCycle, axTiming, axSet;  // parts of 'axes', summed over the 4 axes
};
static void spiPipelined(const uint8_t *tx, uint8_t *rx, uint16_t n) {
  SPI_TypeDef *sp = SPI1;
  uint16_t sent = 0, got = 0;
  __disable_irq();
  while (got < n) {
    if (sent < n && (sp->SR & SPI_SR_TXE) && sent - got < 2) {
      *(volatile uint8_t *)&sp->DR = tx ? tx[sent] : 0xFF;
      sent++;
    }
    if (sp->SR & SPI_SR_RXNE) {
      uint8_t b = *(volatile uint8_t *)&sp->DR;
      if (rx) rx[got] = b;
      got++;
    }
  }
  __enable_irq();
  while (sp->SR & SPI_SR_BSY) {}
}
volatile CycleProfile prof = {0xC0FFEE00};
#define PT() (DWT->CYCCNT)
static void profileBench() {
  for (int i = 0; i < N_AXES; i++)
    if (Step->stepgen_array[i].enable) return;  // only with every channel disabled
  uint32_t t = PT();
  for (int k = 0; k < 100; k++) Step->makeAllPulses();
  prof.pulses100 = PT() - t;  // channels skipped once written
  {
    static stepgen_t dummy[N_AXES];
    for (int i = 0; i < N_AXES; i++) {
      memcpy((void *)&dummy[i], (const void *)&Step->stepgen_array[i], sizeof(stepgen_t));
      dummy[i].enable = 1;
      dummy[i].target_addval = 50000000;  // about 0.2 steps per period
      dummy[i].deltalim = 1000000;
    }
    t = PT();
    for (int k = 0; k < 100; k++)
      for (int i = 0; i < N_AXES; i++) stepgenPulseStepDir(&dummy[i], 10000);
    prof.core400Active = PT() - t;
  }
  // CPU taken by the base period interrupt, dispatch included
  uint32_t c0 = 0, t0 = micros();
  while (micros() - t0 < 5000) c0++;
  pulsesLeft = 1000000;
  baseTimerStart();
  uint32_t c1 = 0;
  int32_t left0 = pulsesLeft;
  t0 = micros();
  while (micros() - t0 < 5000) c1++;
  prof.isrCount = left0 - pulsesLeft;
  pulsesLeft = 0;
  prof.loopIdle = c0;
  prof.loopIsr = c1;
  // SPI: 75 bytes from the ESC's user RAM (0x0F80), as the TxPDO
  uint8_t a[75], b[75];
  spi_use_fast = 0;  // SPI.transfer(), as before
  t = PT();
  ESC_read(0x0F80, a, sizeof(a));
  prof.spiHal75 = PT() - t;
  spi_use_fast = 1;  // the register loop / DMA now in use
  t = PT();
  ESC_read(0x0F80, b, sizeof(b));
  prof.spiFast75 = PT() - t;
  prof.spiSame = memcmp(a, b, sizeof(a)) == 0;
  // Parts, with CS high (the ESC ignores the clocks)
  t = PT();
  spi_fast_transfer(nullptr, a, sizeof(a));
  prof.rawFast75 = PT() - t;
  t = PT();
  SPI.transfer(static_cast<const void *>(nullptr), static_cast<void *>(a), sizeof(a));
  prof.rawHal75 = PT() - t;
  t = PT();
  spi_select(0);
  spi_unselect(0);
  prof.csPair = PT() - t;
  uint8_t ad[2] = {0, 0}, r2[2];
  t = PT();
  spi_fast_transfer(ad, r2, 2);
  prof.addr2 = PT() - t;
  uint8_t c[75];
  t = PT();
  spiPipelined(nullptr, c, sizeof(c));
  prof.rawPipe75 = PT() - t;
  // Compare with the ESC: pipelined ESC_read of 0x0F80 by hand
  {
    uint8_t d[75];
    uint16_t addr = 0x0F80;
    uint8_t hdr[2] = {(uint8_t)(addr >> 5), (uint8_t)(((addr & 0x1F) << 3) | 0x02)}, ign[2];
    static uint8_t term[75];
    term[74] = 0xFF;
    spi_select(0);
    spiPipelined(hdr, ign, 2);
    spiPipelined(term, d, sizeof(d));
    spi_unselect(0);
    prof.pipeSame = memcmp(d, b, sizeof(d)) == 0;
  }
  {
    static _SMmap mp[64];
    alignas(8) static uint8_t pb[80];
    int nm = 0;
    sizeOfPDO(TX_PDO_OBJIDX, &nm, mp, MAX_MAPPINGS_SM3);
    t = PT();
    COE_pdoPack(pb, nm, mp);
    prof.pack75 = PT() - t;
    coe_pdo_fast = 0;
    t = PT();
    COE_pdoPack(pb, nm, mp);
    prof.pack75Old = PT() - t;
    coe_pdo_fast = 1;
    sizeOfPDO(RX_PDO_OBJIDX, &nm, mp, MAX_MAPPINGS_SM2);
    memset(pb, 0, sizeof(pb));  // every axis disabled anyway; unpack writes the RxPDO objects
    uint8_t saved[sizeof(Obj)];
    memcpy(saved, (const void *)&Obj, sizeof(Obj));
    t = PT();
    COE_pdoUnpack(pb, nm, mp);
    prof.unpack54 = PT() - t;
    coe_pdo_fast = 0;
    t = PT();
    COE_pdoUnpack(pb, nm, mp);
    prof.unpack54Old = PT() - t;
    coe_pdo_fast = 1;
    memcpy((void *)&Obj, saved, sizeof(Obj));
  }
  prof.cr1 = SPI1->CR1;
  prof.cr2 = SPI1->CR2;
  prof.sr = SPI1->SR;
  prof.benchRuns++;
}
#else
#define PT() 0u
#endif

void applicationCycle(uint32_t cycleNs, bool outputsValid, bool newOutputs) {
  uint32_t p0 = PT();
  float dt = (float)cycleNs * 1e-9f;

  if (commLostPending) {
    commLostPending = false;
    for (int i = 0; i < N_AXES; i++) Axes[i].communicationLost();
  }

  updateInputs(micros());
  uint32_t p1 = PT();
  Step->updatePositions();
#ifdef CYCLE_PROFILE
  uint32_t a0 = PT(), sumCycle = 0, sumTiming = 0, sumSet = 0;
  prof.upd = a0 - p1;
#endif
  uint8_t errorRegister = 0;
  for (int i = 0; i < N_AXES; i++) {
    stepgen_t &sg = Step->stepgen_array[i];
    MotionFeedback fb = {sg.pos_fb, sg.freq};
    const Cia402Axis_t &a = Obj.Axis[i];
    AxisInputs in;
    in.home = inputActive(a.HomeInput);
    in.posLimit = inputActive(a.PosLimitInput);
    in.negLimit = inputActive(a.NegLimitInput);
    if (a.HomeInput >= 1 && a.HomeInput <= 8) {
      const InputState &st = inputState[a.HomeInput - 1];
      in.homeChanged = st.changed;
      in.homeChangePosition = st.latched ? stepgenFxFromSteps(st.latchCount[i]) : sg.pos_fb;
    }
#ifdef CYCLE_PROFILE
    uint32_t b0 = PT();
#endif
    MotionCommand cmd = Axes[i].cycle(fb, dt, outputsValid, newOutputs, in);
#ifdef CYCLE_PROFILE
    uint32_t b1 = PT();
#endif
    StepTiming_t &t = Obj.StepTiming[i];
    Step->setTiming(i, t.StepLength, t.StepSpace, t.DirSetup, t.DirHold);
#ifdef CYCLE_PROFILE
    uint32_t b2 = PT();
#endif
    Step->setChannel(i, cmd.enable, cmd.positionMode, cmd.position, cmd.velocity,
                     cmd.maxVelocity, cmd.maxAccel, cmd.resync);
#ifdef CYCLE_PROFILE
    sumCycle += b1 - b0;
    sumTiming += b2 - b1;
    sumSet += PT() - b2;
#endif
    if (Axes[i].faulted()) errorRegister |= 0x01;  // generic error

    // 0x60C2 interpolation time period = cycle time (value * 10^index s)
    uint32_t us = cycleNs / 1000;
    if (us % 1000 == 0 && us / 1000 <= 255) {
      Obj.Axis[i].InterpolationTimeValue = us / 1000;
      Obj.Axis[i].InterpolationTimeIndex = -3;
    } else if (us <= 255) {
      Obj.Axis[i].InterpolationTimeValue = us;
      Obj.Axis[i].InterpolationTimeIndex = -6;
    } else {
      Obj.Axis[i].InterpolationTimeValue = us / 100 > 255 ? 255 : us / 100;
      Obj.Axis[i].InterpolationTimeIndex = -4;
    }
  }
  Obj.ErrorRegister = errorRegister;
  uint32_t p2 = PT();
#ifdef CYCLE_PROFILE
  prof.axCycle = sumCycle;
  prof.axTiming = sumTiming;
  prof.axSet = sumSet;
#endif

  if (Obj.BasePeriod != requestedBasePeriod) setBasePeriod(Obj.BasePeriod);
  Step->updateFrequencies(cycleNs);
  uint32_t p3 = PT();
  restartPulseTrain(cycleNs);
#ifdef CYCLE_PROFILE
  prof.inputs = p1 - p0;
  prof.axes = p2 - p1;
  prof.stepFreq = p3 - p2;
  prof.restart = PT() - p3;
#else
  (void)p0; (void)p1; (void)p2; (void)p3;
#endif
}

// One complete process data cycle. fromSync: triggered by SYNC0.
void serveCycle(uint32_t cycleNs, bool fromSync) {
  uint32_t t0 = micros();
  uint32_t q0 = PT();
  uint32_t ev = ESC_ALeventread();  // also refreshes ESCvar.ALevent
  bool newOutputs = (ev & ESCREG_ALEVENT_SM2) != 0;
  uint32_t q1 = PT();

  DIG_process(DIG_PROCESS_WD_FLAG | DIG_PROCESS_OUTPUTS_FLAG);
  uint32_t q2 = PT();
  bool outputsValid = outputsActive();
  if (outputsValid) wasInOp = true;

  if (fromSync && outputsValid) {
    if (!newOutputs) Obj.SmOutParam.SmEventMissed++;
    Obj.SmOutParam.SyncError = newOutputs ? 0 : 1;
    Obj.SmInParam.SmEventMissed = Obj.SmOutParam.SmEventMissed;
    Obj.SmInParam.SyncError = Obj.SmOutParam.SyncError;
  }

  applicationCycle(cycleNs, outputsValid, newOutputs);
  uint32_t q3 = PT();
  DIG_process(DIG_PROCESS_INPUTS_FLAG);
#ifdef CYCLE_PROFILE
  uint32_t q4 = PT();
  prof.alevent = q1 - q0;
  prof.digOut = q2 - q1;
  prof.digIn = q4 - q3;
  prof.total = q4 - q0;
  if (prof.total > prof.maxTotal) prof.maxTotal = prof.total;
  prof.n++;
#else
  (void)q0; (void)q1; (void)q2; (void)q3;
#endif

  // ETG.1020 0x1C32:06 / 0x1C33:06, measured worst case
  uint32_t calcNs = (micros() - t0) * 1000;
  if (calcNs > Obj.SmOutParam.CalcCopyTime) {
    Obj.SmOutParam.CalcCopyTime = calcNs;
    Obj.SmInParam.CalcCopyTime = calcNs;
  }
  Obj.SmOutParam.CycleTimeTooSmall = sync0Overruns;
  Obj.SmInParam.CycleTimeTooSmall = sync0Overruns;
  lastCycleMicros = t0;
}

void setup(void) {
  DebugSerial.begin(115200);
#ifdef CYCLE_PROFILE
  CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
  DWT->CYCCNT = 0;
  DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
#endif
  delay(100);

  for (int i = 0; i < 4; i++) {
    pinMode(OUTPUTS[i], OUTPUT);
    digitalWrite(OUTPUTS[i], LOW);
  }
  for (int i = 0; i < 8; i++) pinMode(INPUTS[i], INPUT);
  pinMode(DAC1_pin, OUTPUT);
  analogWriteResolution(DAC_RESOLUTION_BITS);
  analogWrite(DAC1_pin, 0);

  encoder_config();  // Must be done before the step outputs are configured
  Freq.begin();

  Step = new StepGen3;
  for (int i = 0; i < N_AXES; i++) {
    pinMode(Step->stepPin[i], OUTPUT);
    pinMode(Step->dirPin[i], OUTPUT);
  }

  // Position latch on every input change (after Step exists: the ISRs read it)
  for (int i = 0; i < 8; i++) {
    inputPort[i] = digitalPinToPort(INPUTS[i]);
    inputMask[i] = digitalPinToBitMask(INPUTS[i]);
    inputState[i].level = inputState[i].candidate = digitalRead(INPUTS[i]) == HIGH;
    attachInterrupt(digitalPinToInterrupt(INPUTS[i]), INPUT_ISRS[i], CHANGE);
  }

  baseTimerInit();
  setBasePeriod(BASE_PERIOD);

  ecat_slv_init(&config);  // Also sets the object dictionary default values

  for (int i = 0; i < N_AXES; i++) Axes[i].init(&Obj.Axis[i]);
  setBasePeriod(Obj.BasePeriod);
  Obj.SmOutParam.SyncType = 1;  // SM synchronous until DC is activated
  Obj.SmInParam.SyncType = 0x22;
  lastCycleMicros = micros();
  DebugSerial.println("EaserCAT 3000 CiA402 started");
}

void loop(void) {
  if (sync0Pending) {
    sync0Pending = false;
    serveCycle(sync0CycleNs, true);
    ecat_slv_poll();  // Mailbox and state machine, right after the cycle
    return;
  }

  // Read lastSync0Micros before micros(): the SYNC0 interrupt can update it at any time,
  // and a value newer than 'now' would wrap the difference and look like a lost SYNC0.
  uint32_t lastSync0 = lastSync0Micros;
  bool seen = sync0Seen;
  uint32_t now = micros();
  bool dcActive = ESCvar.dcsync && sync0CycleNs != 0;
  int32_t sinceSync0 = (int32_t)(now - lastSync0);  // since the last SYNC0, or since enabling
  bool dcRunning = dcActive && seen &&
                   sinceSync0 < (int32_t)(3 * (sync0CycleNs / 1000) + 2000);
  if (dcRunning) return;  // Wait for SYNC0, don't disturb it with SPI traffic

  // Before the first SYNC0 the loop polls as usual, so the mailbox and the state machine
  // keep running while the master waits for the SYNC0 start time.
  bool sync0Lost = dcActive && (seen || sinceSync0 >= SYNC0_START_TIMEOUT_US);
  if (sync0Lost && inOp()) {
    // DC was activated but SYNC0 stopped, or never started: synchronization error (ETG.1020)
    Obj.SmOutParam.SyncError = Obj.SmInParam.SyncError = 1;
    ESC_ALstatusgotoerror((ESCsafeop | ESCerror), ALERR_SYNCERROR);
  }

#ifdef CYCLE_PROFILE
  static uint32_t lastBench = 0;
  if (!outputsActive() && now - lastBench > 2000000) {
    lastBench = now;
    profileBench();
  }
#endif
  ecat_slv_poll();
  bool smEvent = (ESCvar.ALevent & ESCREG_ALEVENT_SM2) != 0;
  if (!ESCvar.dcsync) {
    Obj.SmOutParam.SyncType = 1;  // SM synchronous
    Obj.SmInParam.SyncType = 0x22;
  }
  // Housekeeping interval: 1 ms, but in OP wait a bit longer for a late frame
  uint32_t housekeepingUs = outputsActive() ? 2000 : 1000;
  if (!ESCvar.dcsync && smEvent) {
    // SM synchronous: one cycle per received frame
    uint32_t dtNs = (now - lastCycleMicros) * 1000;
    if (dtNs < 100000) dtNs = 100000;
    if (dtNs > 10000000) dtNs = 10000000;
    Obj.SmOutParam.CycleTime = Obj.SmInParam.CycleTime = dtNs;
    serveCycle(dtNs, false);
  } else if (now - lastCycleMicros >= housekeepingUs) {
    serveCycle(housekeepingUs * 1000, false);  // Housekeeping cycle without new outputs
  }
}

////// Interrupts and DC

void sync0Handler(void) {
  // No SPI access here, it would collide with an SPI transfer of the main loop.
  if (sync0Pending) sync0Overruns++;
  lastSync0Micros = micros();
  sync0Seen = true;
  sync0Pending = true;
}

void ESC_interrupt_enable(uint32_t mask) {
  if (mask & ESCREG_ALEVENT_DC_SYNC0) {
    sync0Seen = false;
    lastSync0Micros = micros();  // SYNC0_START_TIMEOUT_US counts from here
    attachInterrupt(digitalPinToInterrupt(SYNC0_PIN), sync0Handler, RISING);
  }
}

void ESC_interrupt_disable(uint32_t mask) {
  if (mask & ESCREG_ALEVENT_DC_SYNC0) {
    detachInterrupt(digitalPinToInterrupt(SYNC0_PIN));
    sync0Pending = false;
    sync0Seen = false;
  }
}

// Called by SOES at PREOP->SAFEOP when the master has activated the SYNC unit
uint16_t dc_checker(void) {
  uint32_t cycle = ESC_SYNC0cycletime();  // ns
  uint32_t minCycle = 250000;             // 0x1C32:05
  if (cycle < minCycle || cycle > 100000000 || cycle < 2 * (uint32_t)Step->basePeriodNs)
    return ALERR_DCSYNC0CYCLETIME;
  sync0CycleNs = cycle;
  ESCvar.dcsync = 1;
  Obj.SmOutParam.SyncType = 2;  // DC SYNC0
  Obj.SmInParam.SyncType = 2;
  Obj.SmOutParam.CycleTime = Obj.SmInParam.CycleTime = cycle;
  return 0;
}
